// Builds the site with BASE_PATH=/fair into a temporary directory and checks the result:
// the localized pages exist and every internal link starts with the base path.
// Usage: npm run check:base-path
// The paraglide runtime in src/lib/paraglide is regenerated by every build, so run
// `npm run build` afterwards to restore the files for the normal (no base path) build.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';

const BASE = '/fair';
const outDir = mkdtempSync(join(tmpdir(), 'fair-base-path-'));
const failures = [];

function fail(message) {
	failures.push(message);
}

function htmlFiles(dir) {
	return readdirSync(dir).flatMap((name) => {
		const full = join(dir, name);
		if (statSync(full).isDirectory()) return name === '_app' ? [] : htmlFiles(full);
		return name.endsWith('.html') ? [full] : [];
	});
}

// Attribute values of href, src and action that are not external, in-page or special schemes.
function internalLinks(html) {
	const links = [];
	for (const match of html.matchAll(/\b(?:href|src|action)\s*=\s*(?:"([^"]*)"|'([^']*)')/gi)) {
		const value = (match[1] ?? match[2]).trim();
		if (value === '' || value.startsWith('#')) continue;
		if (/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(value)) continue;
		links.push(value);
	}
	return links;
}

const build = spawnSync('npm', ['run', 'build'], {
	stdio: ['ignore', 'pipe', 'pipe'],
	encoding: 'utf8',
	env: { ...process.env, BASE_PATH: BASE, BUILD_DIR: outDir }
});
if (build.status !== 0) {
	console.error(build.stdout.slice(-3000), build.stderr.slice(-3000));
	fail(`build with BASE_PATH=${BASE} failed (exit ${build.status})`);
}

if (failures.length === 0) {
	const toolPage = 'en/tools/f-uji.html';
	const pages = [
		'en.html',
		'es.html',
		'en/about.html',
		'es/about.html',
		'en/wizard.html',
		'es/wizard.html'
	];
	for (const page of [...pages, toolPage]) {
		if (!existsSync(join(outDir, page))) fail(`missing ${page}`);
	}
	const notFound = join(outDir, '404.html');
	if (
		!existsSync(notFound) ||
		!readFileSync(notFound, 'utf8').includes(`<base href="${BASE}/" />`)
	) {
		fail(`404.html must set <base href="${BASE}/" />`);
	}
	for (const file of htmlFiles(outDir)) {
		const name = relative(outDir, file);
		for (const link of internalLinks(readFileSync(file, 'utf8').replace(/<base\s[^>]*>/gi, ''))) {
			// static/404.html is served as is and must use document-relative links.
			if (name === '404.html') {
				if (link.startsWith('/')) fail(`${name}: absolute link ${link}`);
			} else if (link !== BASE && !link.startsWith(`${BASE}/`) && !link.startsWith('?')) {
				fail(`${name}: internal link outside ${BASE}: ${link}`);
			}
		}
	}
}

rmSync(outDir, { recursive: true, force: true });

if (failures.length > 0) {
	console.error(`check:base-path failed (${failures.length}):`);
	for (const message of [...new Set(failures)].slice(0, 30)) console.error(`  ${message}`);
	process.exit(1);
}
console.log(`check:base-path ok: pages exist and all internal links start with ${BASE}`);
